body:
Oh my bad on the title it's fixed now.

Here a sample of what's not working :

```java
package org.acme;

import io.smallrye.mutiny.Multi;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.MediaType;
import org.jboss.resteasy.reactive.RestMulti;

@Path("/")
public class GreetingResource {
    @GET
    @Path("/notworking")
    public Multi<byte[]> notWorking() {
        Multi<byte[]> multi = Multi.createFrom().item("Hello from RESTEasy Reactive".getBytes());
        return RestMulti.fromMultiData(multi).header("Content-Type", MediaType.TEXT_PLAIN).build();
    }

    @GET
    @Path("/working")
    @Produces(MediaType.APPLICATION_ATOM_XML)
    public Multi<byte[]> working() {
        Multi<byte[]> multi = Multi.createFrom().item("Hello from RESTEasy Reactive".getBytes());
        return RestMulti.fromMultiData(multi).header("Content-Type", MediaType.TEXT_PLAIN).build();
    }

    @GET
    @Path("/workingString")
    public Multi<String> workingWithString() {
        Multi<String> multi = Multi.createFrom().item("Hello from RESTEasy Reactive");
        return RestMulti.fromMultiData(multi).header("Content-Type", MediaType.TEXT_PLAIN).build();
    }
}
```

`Multi<String>` works as expected, but you have to specify a `@Produces` bean for  `Multi<byte[]>` otherwise you'll get an error. A simple workaround is to add a random `@Produces` bean for the endpoint, but I don't know if it's the intended behavior.
